char firstUniq(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) count[c - 'a']++;   // pass 1
    for (char c : s.toCharArray())                     // pass 2: original order
        if (count[c - 'a'] == 1) return c;
    return '_';   // sentinel: no unique character
}

// s = "leetcode"
// counts: l1 e3 t1 c1 o1 d1
// pass 2: 'l' count 1 -> return 'l'
// s = "aabb" -> pass 2 finds none -> '_'
```

