int longestSubarray(int[] nums, int k) {
    Map<Integer,Integer> first = new HashMap<>();
    first.put(0, -1);                 // empty prefix before index 0
    int sum = 0, best = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += nums[i];
        if (first.containsKey(sum - k))           // earlier prefix gives sum k
            best = Math.max(best, i - first.get(sum - k));
        first.putIfAbsent(sum, i);                // keep EARLIEST index only
    }
    return best;
}

// nums = {1, -1, 5, -2, 3}, k = 3
// prefix: 1,0,5,3,6 ; sum-k seen -> best length 4 (subarray 1,-1,5,-2)
